        key=lambda o:(min(r for r,c in o[1]) if up else -max(r for r,c in o[1]))
    else:
        axis='h'; left=(0 in border_cols); step=-1 if left else 1
        blocked={(r,c) for r in range(h) for c in border_cols}
        key=lambda o:(min(c for r,c in o[1]) if left else -max(c for r,c in o[1]))
    objs=[]
