        if any((r,c) in blocked for r,c in cells): continue
        objs.append([col,cells])
    occupied=set(blocked)
    for _,cells in objs: occupied|=set(cells)
    def can(cells,newcells):
        return all((r,c) not in occupied-set(cells) and (r,c) not in blocked for r,c in newcells)
    while True:
        moved=False
        for o in sorted(objs,key=key):
            col,cells=o
            dr,dc=(step,0) if axis=='v' else (0,step)
